// Dynamic Exception Specification (Deprecated C++11, Removed C++17)
// Runtime failure (std::unexpected) if violated before C++17.
void risky_func() throw(std::runtime_error, std::bad_alloc);

// Pre-C++17 equivalent of noexcept(true)
void legacy_nothrow() throw();

// Violation example (Pre-C++17):
void fail() throw() {
    throw 42; // Calls std::unexpected()
}

// Modern Exception Specification (C++11)
// Violation results in std::terminate() (fast failure)
void guaranteed_safe() noexcept; // noexcept(true)

// Function that may throw
void may_throw() noexcept(false);

// Conditional safety guarantee
template <typename T>
void cond_safe() noexcept(
    std::is_nothrow_move_constructible_v<T>
);

// Note: C++17 onward, dynamic specs are ignored by compiler
// except for throw() which is treated as noexcept(true).
